INSERT OR REPLACE INTO resume_experience (id, title, company, employment_type, location, start_date, end_date, bullets, tech_stack, published, sort) VALUES ('rexp-7', 'Software Engineer', 'PT Kazeto Putra Perkasa', 'Contract', 'Jakarta', 'Mar 2023', 'Jan 2024', '["Joined through invitation while mentoring at Pilihanmu to collaborate on a related MSIB project.","Built hskakseto.sch.id (Homeschooling Kak Seto platform) using Next.js, TypeScript, and TailwindCSS.","Applied TDD and Agile Scrum, aligning UI/UX goals with frontend implementation and mentoring interns during development."]', 'Next.js, TypeScript, TailwindCSS, Node.js, Docker, Git, Agile Scrum, TDD', 1, 6);
INSERT OR REPLACE INTO resume_experience (id, title, company, employment_type, location, start_date, end_date, bullets, tech_stack, published, sort) VALUES ('rexp-8', 'Software Developer', 'Homeschooling Kak Seto', 'Full-time', 'Depok · On-site', 'Jan 2023', 'Dec 2023', '["Joined Homeschooling Kak Seto team directly recruited by the director to contribute to the development of the Pilih Jurusan online psychological test application project.","Led Intern UI/UX Designers as Mentor from Kampus Merdeka Program Batch 5 for both Homeschooling Kak Seto and Pilih Jurusan Web App, overseeing design implementation and feature enhancements.","Developed and maintained Homeschooling Kak Seto website with TDD Agile Scrum using NextJS, Typescript, TailwindCSS, Cloudinary, and Firebase."]', 'Next.js, TypeScript, React.js, TailwindCSS, Cloudinary, Firebase, Figma, Agile Scrum', 1, 7);
INSERT OR REPLACE INTO resume_experience (id, title, company, employment_type, location, start_date, end_date, bullets, tech_stack, published, sort) VALUES ('rexp-9', 'Software Developer', 'Pilih Jurusan', 'Part-time', 'Jakarta · Remote', 'Feb 2022', 'Dec 2023', '["Led team of intern UI/UX designers and front-end developers from Kampus Merdeka program to develop websites for https://pilihjurusan.id and Homeschooling Kak Seto https://hskakseto.sch.id.","Led UI/UX Design Team and managed UI Kit of Pilihjurusan Test Psychology Product.","Improved website responsiveness and performance by 30% by limiting API requests and adding lazy load.","Built and designed simple and fluid new responsive admin dashboard.","Developed and maintained the Pilih Jurusan Psychology Testing Website with TDD Agile Scrum development methodology using Fullstack Laravel, InertiaJS, TailwindCSS, and Docker."]', 'Laravel, Inertia.js, TailwindCSS, Docker, Webpack, Alpine.js, Figma, Agile Scrum', 1, 8);
INSERT OR REPLACE INTO resume_experience (id, title, company, employment_type, location, start_date, end_date, bullets, tech_stack, published, sort) VALUES ('rexp-10', 'Information Technology (Kampus Merdeka Batch 1)', 'Pilih Jurusan', 'Apprenticeship', 'Jakarta · Remote', 'Aug 2021', 'Feb 2022', '["Successfully developed and implemented a dynamic theme-changing system, which elicited positive responses from users (at least 7 out of 10 users reported feeling assisted and comfortable during prolonged testing sessions).","Mastered TDD Agile Scrum development methodology through the Agile Innovation Internship Program at MSIB Kampus Merdeka.","Optimized website performance at least 40% better and achieved better SEO by maximizing semantic elements and precise utilization of assets.","Developed and maintained the Pilih Jurusan Psychology Testing Website with TDD Agile Scrum using Fullstack MVC CodeIgniter v3, TailwindCSS."]', 'CodeIgniter, TailwindCSS, MySQL, Agile Scrum, SEO', 1, 9);
