INSERT OR REPLACE INTO testimonial (id, name, role, image, message, social_links, created_at) VALUES ('tst-ogant', 'Ogant Biru Samudera', 'Product Designer at Glints', '/testimonials/ogant.jpg', 'I had the privilege of working with Wahyudi as a mentor during my Magang Merdeka internship. As an experienced UX Specialist, he explained complex concepts in a straightforward manner and was dedicated to helping me understand UI/UX principles. Highly recommended.', NULL, 1695168000);
INSERT OR REPLACE INTO testimonial (id, name, role, image, message, social_links, created_at) VALUES ('tst-rizqy', 'Rizqy Andriansyah', 'Frontend Developer', '/testimonials/rizqy.jpg', 'I worked with Wahyudi during our time at Dumbways ID bootcamp. As my coding partner, he consistently turned designs into responsive, visually appealing websites with impressive attention to detail. A reliable, dedicated team player with a positive attitude.', NULL, 1678665600);

